; ==================================================================
; MAIN PROGRAM
; ==================================================================
MAIN_PROGRAM:
    ; Set up a simple pattern in VRAM for testing
    LD HL, #0000        ; VRAM address 0 (pattern table)
    LD A, #FF           ; Pattern: all bits set
    CALL WRTVRM         ; Write to VRAM

    ; Main program loop
MAIN_LOOP:
    ; Just halt and wait
    HALT
    JP MAIN_LOOP

; ==================================================================
; BIOS FUNCTIONS
; ==================================================================
CHGMOD: EQU #005F      ; Change screen mode
CLS:    EQU #00C3      ; Clear screen
WRTVRM: EQU #004D      ; Write to VRAM

    END
